function validate([head]) {
  if (head.length < 3 || head.length > 200000) return 'The list needs 3 to 200000 nodes.';
  if (head.some(v => v < 0 || v > 1000)) return 'Each node value is between 0 and 1000.';
  if (head[0] !== 0 || head[head.length - 1] !== 0) return 'The list must start and end with 0.';
  for (let i = 1; i < head.length; i++) if (head[i] === 0 && head[i - 1] === 0) return 'Two zeros cannot be next to each other.';
  return null;
}

