function generate(rand, size) {
  const list = [0];
  if (size === 'large') {
    while (list.length < 1990) {
      const run = 1 + Math.floor(rand() * 6);
      for (let k = 0; k < run; k++) list.push(1 + Math.floor(rand() * 1000));
      list.push(0);
    }
    return [list];
  }
  const runs = 1 + Math.floor(rand() * 4);
  const top = rand() < 0.5 ? 5 : 1000;
  for (let r = 0; r < runs; r++) {
    const run = 1 + Math.floor(rand() * 3);
    for (let k = 0; k < run; k++) list.push(1 + Math.floor(rand() * top));
    list.push(0);
  }
  return [list];
}
